<?php namespace App\Filament\Resources\ParentMeetingResource\Pages;use App\Filament\Resources\ParentMeetingResource;use App\Services\PeriodGuard;use Filament\Resources\Pages\CreateRecord;class CreateParentMeeting extends CreateRecord{protected static string $resource=ParentMeetingResource::class;protected function mutateFormDataBeforeCreate(array $d):array{$p=request()->attributes->get('academic_period');if($p){PeriodGuard::writable($p->id);$d['academic_period_id']=$p->id;}return $d;}}